import json
from glob import glob
def task_func(directory, string):
    import os
    matched_files = []
    for file_path in glob(os.path.join(directory, '**/*.json'), recursive=True):
        with open(file_path, 'r') as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                continue
            def contains(obj):
                if isinstance(obj, str):
                    return string in obj
                if isinstance(obj, dict):
                    return any(contains(v) for v in obj.values())
                if isinstance(obj, list):
                    return any(contains(v) for v in obj)
                return False
            if contains(data):
                matched_files.append(file_path)
    return matched_files

import json
import re
import pandas as pd
def task_func(json_str):
    try:
        data = json.loads(json_str)
        if not isinstance(data, dict) or not data:
            return pd.DataFrame()
    except:
        return pd.DataFrame()

    def process(v):
        if isinstance(v, (int, float)):
            return float(v * 2)
        if isinstance(v, list):
            return [process(x) for x in v]
        if isinstance(v, str):
            match = re.search(r'-?\d+(?:\.\d+)?', v)
            if match:
                return float(match.group()) * 2
        return v

    processed_data = {k: process(v) for k, v in data.items()}
    return pd.DataFrame([processed_data])

import json
